#!/bin/bash
#
#  acquisition backend regression and benchmark on recorded IF data
#
#  usage: bench_acq.sh [IF_file [out_dir [backend ...]]]
#
#  Each backend runs the same signal set (acq_sigs.sh) and is compared with the
#  CPU golden results (golden_cpu.txt, generated by the original PocketSDR).
#  A backend with prefix "fftw+" runs with the bench linked with FFTW and FFTW
#  wisdom ($WISDOM, generated by FFTW_PATIENT at the first run) instead of
#  PocketFFT (e.g. fftw+cpu: original CPU acquisition with FFTW).
#  Set TASKSET (e.g. "taskset -c 12") to run on specific CPU cores.
#  Set SIGFILE to use another signal set (e.g. long_sigs.sh) and REF to compare
#  with another reference (e.g. res_cpu.txt of the same run).
#
SCRIPT_DIR=$(cd "$(dirname "$0")" && pwd)
cd "$SCRIPT_DIR" || exit 1
FILE=${1:-$HOME/IFdata/L1B1G1L2G2L5E5bL6_20250327_0248_16MHz.bin}
OUT=${2:-./out}
shift 2 2>/dev/null
BACKENDS=${@:-cpu fftw+cpu npu ov:NPU,direct fftw+cpu_opt}
BENCH=../utest/bench_sdr_acq
BENCH_FFTW=../utest/bench_sdr_acq_fftw
WISDOM=${WISDOM:-$OUT/fftw_wisdom.txt}
export SDR_ACC_PATH=${SDR_ACC_PATH:-$SCRIPT_DIR/../../lib/linux}
source "${SIGFILE:-acq_sigs.sh}"
REF=${REF:-golden_cpu.txt}

mkdir -p "$OUT"
make -C ../utest bench_sdr_acq bench_sdr_acq_fftw > /dev/null || exit 1
WARM=${WARM:-"-sig L1CA -prn 1 -rfch 1 -sig E1B -prn 1 -rfch 1"}
$BENCH -f 16 -fo $FO -acc npu $WARM "$FILE" > /dev/null 2>&1 # warm-up (NPU
# model compile and cache)
$BENCH_FFTW -f 16 -fo $FO -wisdom "$WISDOM" $SIGS -sig L1CA -prn 1 -rfch 1 \
    -n 0 "$FILE" > /dev/null # generate FFTW wisdom if not exist
for be in $BACKENDS; do
    name=${be//[:,+]/_}
    echo "=== backend: $be"
    if [ "${be#fftw+}" != "$be" ]; then
        $TASKSET $BENCH_FFTW -f 16 -fo $FO -acc ${be#fftw+} -wisdom "$WISDOM" \
            $SIGS -o "$OUT/res_$name.txt" "$FILE" > "$OUT/log_$name.txt" 2>&1
    else
        $TASKSET $BENCH -f 16 -fo $FO -acc $be $SIGS -o "$OUT/res_$name.txt" \
            "$FILE" > "$OUT/log_$name.txt" 2>&1
    fi
    grep '^#' "$OUT/log_$name.txt"
    [ -f "$REF" ] && python3 cmp_acq.py "$REF" "$OUT/res_$name.txt" | tail -3
done
